                    writer.WriteNull("resolution");
            }

            if (supportTicket.Impact == null)
                writer.WriteNull("impact");
            else
            {
                var impactRawValue = SupportReportImpactValueConverter.ToJsonValue(supportTicket.Impact.Value);
                if (impactRawValue != null)
                    writer.WriteString("impact", impactRawValue);
                else
                    writer.WriteNull("impact");
            }

            if (supportTicket.Task != null)
                writer.WriteString("task", supportTicket.Task);
            else
                writer.WriteNull("task");

            if (supportTicket.Tool != null)
                writer.WriteString("tool", supportTicket.Tool);
            else
                writer.WriteNull("tool");

            if (supportTicket.Error != null)
                writer.WriteString("error", supportTicket.Error);
            else
                writer.WriteNull("error");

            if (supportTicket.Suggestion != null)
                writer.WriteString("suggestion", supportTicket.Suggestion);
            else
                writer.WriteNull("suggestion");

            if (supportTicket.Session != null)
                writer.WriteString("session", supportTicket.Session);
            else
                writer.WriteNull("session");

            if (supportTicket.FromFeedbackId != null)
                writer.WriteString("from_feedback_id", supportTicket.FromFeedbackId);
            else
                writer.WriteNull("from_feedback_id");

            if (supportTicket.Messages != null)
            {
                writer.WritePropertyName("messages");
                JsonSerializer.Serialize(writer, supportTicket.Messages, jsonSerializerOptions);
            }
            else
                writer.WriteNull("messages");
        }
    }
